WHEN MATCHED AND (t.[Source] <> 'gazetaonline-2026-10' OR t.[ModelId] <> s.[ModelId] OR t.[Year] <> s.[Year] OR t.[Name] COLLATE Latin1_General_100_BIN2 <> s.[Name] COLLATE Latin1_General_100_BIN2) THEN UPDATE SET [ModelId] = s.[ModelId], [Year] = s.[Year], [Name] = s.[Name], [Source] = 'gazetaonline-2026-10'
