WHEN NOT MATCHED THEN INSERT ([Id], [Kind], [ModelId], [Year], [Name], [Source]) VALUES (s.[Id], s.[Kind], s.[ModelId], s.[Year], s.[Name], 'gazetaonline-2026-10');

