-- Guarda de acentos corrompidos (ASCII de proposito): aborta e desfaz tudo se o arquivo foi lido sem '-f 65001'.
DECLARE @Corrupted nvarchar(100) = N'%[' + NCHAR(194) + NCHAR(195) + N'][' + NCHAR(128) + N'-' + NCHAR(191)
    + NCHAR(338) + NCHAR(339) + NCHAR(352) + NCHAR(353) + NCHAR(376) + NCHAR(381) + NCHAR(382) + NCHAR(402) + NCHAR(710) + NCHAR(732)
    + NCHAR(8211) + N'-' + NCHAR(8250) + NCHAR(8364) + NCHAR(8482) + N']%';
IF EXISTS (
    SELECT 1 AS Found FROM [VehicleBrands] WHERE [Source] = 'gazetaonline-2026-10' AND [Name] COLLATE Latin1_General_100_BIN2 LIKE @Corrupted
    UNION ALL SELECT 1 AS Found FROM [VehicleModels] WHERE [Source] = 'gazetaonline-2026-10' AND [Name] COLLATE Latin1_General_100_BIN2 LIKE @Corrupted
    UNION ALL SELECT 1 AS Found FROM [VehicleVersions] WHERE [Source] = 'gazetaonline-2026-10' AND [Name] COLLATE Latin1_General_100_BIN2 LIKE @Corrupted
)
